<template><div class="login-page flex flex-center"><q-card class="login-card"><div class="login-card__brand"><h1 class="login-card__title">ตั้งรหัสผ่านใหม่</h1></div><q-form class="login-card__form" @submit.prevent="submit"><q-input v-model="password" type="password" label="รหัสผ่านใหม่" outlined :rules="[valid]" /><q-input v-model="confirm" type="password" label="ยืนยันรหัสผ่าน" outlined :rules="[same]" /><q-banner v-if="message" dense rounded :class="success ? 'bg-positive text-white' : 'login-card__error'">{{ message }}</q-banner><q-btn type="submit" unelevated no-caps label="บันทึกรหัสผ่าน" :loading="loading" class="login-card__submit" /></q-form></q-card></div></template>
<script setup lang="ts">
import { ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { authApiService } from '@/services/auth-api.service';
const route = useRoute(); const router = useRouter(); const password = ref(''); const confirm = ref(''); const loading = ref(false); const message = ref(''); const success = ref(false); const valid = (v: string) => v.length >= 8 || 'อย่างน้อย 8 ตัวอักษร'; const same = (v: string) => v === password.value || 'รหัสผ่านไม่ตรงกัน';
async function submit(): Promise<void> { const token = String(route.query.token || ''); if (!token || password.value.length < 8 || password.value !== confirm.value) return; loading.value = true; try { await authApiService.resetPassword(token, password.value); success.value = true; message.value = 'ตั้งรหัสผ่านใหม่สำเร็จ กำลังพาไปหน้าเข้าสู่ระบบ'; setTimeout(() => void router.replace('/login'), 1200); } catch { message.value = 'ลิงก์ไม่ถูกต้องหรือหมดอายุ'; } finally { loading.value = false; } }
</script>
